// Generated by OrchestKit Claude Plugin
// Created: 2026-08-04

/**
 * Agent registry — the set of subagent_type values that actually resolve.
 *
 * Why this exists: nothing validated a spawn target against the agents that
 * exist. Three failures came out of that gap in two days — /ork:assess spawning
 * four agents by bare name, a Workflow stage typed `ork:business-case` (a SKILL,
 * not an agent) dying with a generic "parallel[N] failed", and an advisor that
 * goes silent whenever the string `agentType` appears anywhere in a script.
 *
 * Source of truth is the AGENT DIRECTORY, deliberately:
 *   - plugins/ork/.claude-plugin/plugin.json has no `agents` key at all
 *   - manifests/ork.json has "agents": "all" — a string, not a list
 * Neither can enumerate. Do not "simplify" this to read a manifest.
 *
 * Rooted at getPluginRoot(), NOT getProjectDir(). subagent-validator.ts made
 * that mistake: in any consumer project there is no <project>/agents/, so its
 * valid set collapsed to the six builtins and every ork:* read as unknown.
 */

import { existsSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { getPluginRoot, getProjectDir } from './paths.js';

/**
 * Claude Code built-in agent types. These are correctly spawned BARE — they
 * carry no plugin namespace. Mirrors subagent-validator.ts BUILTIN_TYPES.
 */
export const BUILTIN_AGENT_TYPES: ReadonlySet<string> = new Set([
  'general-purpose',
  'Explore',
  'Plan',
  'claude-code-guide',
  'statusline-setup',
  'Bash',
  'claude',
]);

/** Docs use <placeholder> forms; they are illustrative, never dispatched. */
function isPlaceholder(value: string): boolean {
  return value.startsWith('<') || value.includes('${') || value.includes('{{');
}

function readAgentDir(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((f) => f.endsWith('.md'))
    .map((f) => f.slice(0, -3))
    .filter((n) => !['README', 'INDEX', 'CONTRIBUTING'].includes(n));
}

let cached: ReadonlySet<string> | null = null;

/**
 * Bare names of every ork agent that exists, e.g. "security-auditor".
 *
 * Checks the shipped plugin directory first, then the source tree, so this
 * resolves both when installed as a plugin and when running inside the
 * orchestkit repo itself (where CLAUDE_PLUGIN_ROOT points at plugins/ork).
 */
export function getOrkAgentNames(): ReadonlySet<string> {
  if (cached) return cached;
  // Walk UP from each base. Tests and hooks run with cwd anywhere from the
  // repo root to src/hooks, and when installed CLAUDE_PLUGIN_ROOT points at
  // plugins/ork. A fixed list of joins silently returns an empty set from the
  // wrong depth, and an empty registry degrades this validator to allow-all —
  // the exact inert-check failure this file exists to replace.
  const bases = [getPluginRoot(), getProjectDir(), process.cwd()];
  const suffixes = [
    ['agents'],
    ['plugins', 'ork', 'agents'],
    ['src', 'agents'],
  ];
  const names = new Set<string>();
  for (const base of bases) {
    let dir = base;
    for (let up = 0; up < 5 && names.size === 0; up++) {
      for (const suffix of suffixes) {
        for (const n of readAgentDir(join(dir, ...suffix))) names.add(n);
      }
      const parent = dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
    if (names.size > 0) break;
  }
  cached = names;
  return cached;
}

/** Test seam. */
export function resetAgentRegistryCache(): void {
  cached = null;
}

export type SpawnTargetVerdict =
  | { kind: 'ok' }
  | { kind: 'skip' } // placeholder, empty, or another plugin's namespace
  | { kind: 'bare'; suggestion: string } // bare name that IS a real ork agent
  | { kind: 'unknown'; suggestion: string | null }; // ork:x where x does not exist

/** Levenshtein, small and bounded — inputs are short agent slugs. */
function distance(a: string, b: string): number {
  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  const cur = new Array<number>(b.length + 1).fill(0);
  for (let i = 1; i <= a.length; i++) {
    cur[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(cur[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost);
    }
    for (let j = 0; j <= b.length; j++) prev[j] = cur[j];
  }
  return prev[b.length];
}

/** Nearest real agent name, or null when nothing is close enough to suggest. */
export function nearestAgent(value: string): string | null {
  const names = getOrkAgentNames();
  let best: string | null = null;
  let bestD = Infinity;
  for (const n of names) {
    const d = distance(value, n);
    if (d < bestD) {
      bestD = d;
      best = n;
    }
  }
  // Half the length is a generous ceiling; beyond it a "suggestion" is noise.
  return best !== null && bestD <= Math.max(3, Math.floor(value.length / 2)) ? best : null;
}

/**
 * Classify one spawn target.
 *
 * Non-ork namespaces (vercel:, hq-ext:, posthog:, ...) return 'skip'. We cannot
 * enumerate another plugin's registry, and guessing would produce false
 * positives on perfectly valid spawns.
 */
export function classifySpawnTarget(raw: string): SpawnTargetVerdict {
  const value = raw.trim().replace(/^['"]|['"]$/g, '');
  if (!value || isPlaceholder(value)) return { kind: 'skip' };
  if (BUILTIN_AGENT_TYPES.has(value)) return { kind: 'ok' };

  const colon = value.indexOf(':');
  if (colon !== -1) {
    const ns = value.slice(0, colon);
    const name = value.slice(colon + 1);
    if (ns !== 'ork') return { kind: 'skip' };
    if (!name || isPlaceholder(name)) return { kind: 'skip' };
    if (getOrkAgentNames().has(name)) return { kind: 'ok' };
    return { kind: 'unknown', suggestion: nearestAgent(name) };
  }

  // No namespace. Only a problem when it names a real ork agent: that is the
  // #2371 failure, where the spawn looks right and dies at dispatch.
  if (getOrkAgentNames().has(value)) return { kind: 'bare', suggestion: `ork:${value}` };

  // An unrecognised bare word is left alone: it may be a builtin we do not
  // know yet, or another plugin's agent spawned without a namespace.
  return { kind: 'skip' };
}

/** Human-readable reason for an ask prompt, or null when the target is fine. */
export function explainSpawnTarget(raw: string): string | null {
  const verdict = classifySpawnTarget(raw);
  if (verdict.kind === 'ok' || verdict.kind === 'skip') return null;
  if (verdict.kind === 'bare') {
    return (
      `subagent_type "${raw}" is a bare name. Plugin agents only resolve namespaced, ` +
      `so this fails at dispatch with "Agent type not found" (#2371). ` +
      `Use "${verdict.suggestion}".`
    );
  }
  const tail = verdict.suggestion
    ? ` Closest registered agent: "ork:${verdict.suggestion}".`
    : ` No similarly-named agent exists; it may be a SKILL rather than an agent (#3279).`;
  return `subagent_type "${raw}" is not a registered agent.${tail}`;
}
